      <html>
        <head>
          <title>File Upload Test</title>
          <style>
            body { font-family: Arial, sans-serif; padding: 20px; }
            .file-upload-container { margin: 20px 0; }
            input[type="file"] { margin: 10px 0; }
            .file-info { margin-top: 20px; padding: 10px; border: 1px solid #ccc; }
            .file-name { font-weight: bold; }
            .file-size { color: #666; }
            .error { color: red; }
          </style>
        </head>
        <body>
          <div class="file-upload-container">
            <h1>File Upload</h1>
            <input type="file" id="fileInput" aria-label="Select file" />
            <div id="fileInfo" class="file-info" style="display: none;">
              <div class="file-name" id="fileName"></div>
              <div class="file-size" id="fileSize"></div>
            </div>
            <div id="errorMessage" class="error" style="display: none;"></div>
          </div>
          <script>
            const fileInput = document.getElementById('fileInput');
            const fileInfo = document.getElementById('fileInfo');
            const fileName = document.getElementById('fileName');
            const fileSize = document.getElementById('fileSize');
            const errorMessage = document.getElementById('errorMessage');

            fileInput.addEventListener('change', function(e) {
              errorMessage.style.display = 'none';
              errorMessage.textContent = '';

              if (this.files && this.files.length > 0) {
                const file = this.files[0];
                const maxSize = 10 * 1024 * 1024; // 10MB

                if (file.size > maxSize) {
                  errorMessage.textContent = 'File size exceeds 10MB limit';
                  errorMessage.style.display = 'block';
                  fileInfo.style.display = 'none';
                  return;
                }

                fileName.textContent = 'File Name: ' + file.name;
                fileSize.textContent = 'File Size: ' + formatFileSize(file.size);
                fileInfo.style.display = 'block';
              } else {
                fileInfo.style.display = 'none';
              }
            });

            function formatFileSize(bytes) {
              if (bytes === 0) return '0 Bytes';
              const k = 1024;
              const sizes = ['Bytes', 'KB', 'MB', 'GB'];
              const i = Math.floor(Math.log(bytes) / Math.log(k));
              return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
            }
          </script>
        </body>
      </html>
